export const ROOM_ASPECT = 2752 / 1536;

export type CaseId = 'about' | 'work' | 'projects' | 'dreams' | 'stories' | 'resume' | 'specimens';

export type Box = { left: number; top: number; width: number; height: number };

export type RoomObject = {
  id: CaseId;
  object: string; // what it is in the room
  label: string; // what it opens
  src: string;
  activeSrc?: string; // e.g. the open drawer while its file is open
  activeBox?: Box;
  box: Box;
  z: number;
};

